def calculate_b_squared(a):
    # b^2 = a(a^2 - 2a - 1) / (a - 2)
    numerator = a * (a**2 - 2*a - 1)
    denominator = a - 2

    if denominator == 0:
        return None # Should not happen for a > 3

    b_squared = numerator / denominator
    return b_squared

def is_perfect_square(n):
    if n < 0:
        return False
    if n == 0:
        return True
    root = int(n**0.5)
    return root * root == n

print("--- Testing Integer a > 3 ---")
for a in range(4, 8): # Test a=4, 5, 6, 7
